\label{thm:GeneralBogoliouboff}
  Let $d\in \mathbb N$, $d\geq 3$, and let $c_1,\dots, c_d\in \mathbb Z$ be such that
  \begin{enumerate}
  \item $c_iG$ has finite index in $G$ for each $i$,
  \item\label{hyp:cicj}  $(c_{d-1}+c_{d})G$, has finite index in $G$,  and
   \item $q$ divides $\sum c_i$.
\end{enumerate}
If $A\subset G$ has $d^*(A)>0$, then $\vec{c}\cdot A$ contains a Bohr neighborhood of $0$ in $G$.

\label{lem:Reduction}
  Let $A\subset G$ and let $c_1,\dots, c_d$ satisfy the hypothesis of Theorem \ref{thm:GeneralBogoliouboff}. Then there is a compact abelian group $K$ with Haar probability measure $m$, an $m$-measurable  $\tilde{f}:K\to [0,1]$ with $\int \tilde{f}\, dm=d^*(A)$, and a homomorphism $\rho:G\to K$ with $\overline{\rho(G)}=K$ such that
  \[
  \phi(t):=\int_{K^d} \tilde{f}(k+c_ds_1)\tilde{f}(k+c_ds_2)\cdots \tilde{f}(k+c_{d}s_{d-1}) \tilde{f}\Bigl(k+\rho(t)-\sum_{i=1}^{d-1} c_is_i\Bigr) \, dk\, ds_1\, ds_2\, \dots \, ds_{d-1}
  \]
  satisfies $c_d\operatorname{supp}(\phi)\subset \vec{c}\cdot A$.

\label{lem:Convolution} Let $\vec{c}\in \mathbb Z^d$ satisfy hypothesis (3) of Theorem \ref{thm:GeneralBogoliouboff}, let $A\subset G$,  and write $1_A$ for its characteristic function.  Define $J: G^{d+1}\to [0,1]$  and $J_0\subset G$ by
\begin{align*}
&J(h,g_1,\dots,g_{d-1};t):=1_A(h+c_dg_1)1_A(h+c_dg_2)\cdots 1_A(h+c_{d}g_{d-1}) 1_A\Bigl(h+t-\sum_{i=1}^{d-1} c_ig_i\Bigr)\\
&J_0:=\{t\in G: \exists h, g_1,\dots, g_{d-1} \in G \text{ with } J(h,g_1,\dots, g_{d-1};t)>0,  c_ig_i \text{  mutually distinct}\},
\end{align*}
 we have
\begin{equation}\label{eqn:J0A}
c_dJ_0 \subset \vec{c}\cdot A.
\end{equation}
Furthermore, setting
\begin{align*}
&\tilde{J}(g_1,\dots,g_{d-1};t):=d^*(\{h:J(h,g_1,\dots,g_{t-1};t)>0\})\\
&\tilde{J}_0:=\{t\in G: \exists g_1,\dots, g_{d-1}\in G \text{ with } \tilde{J}(g_1,\dots,g_{d-1};t)>0, c_ig_i \text{ mutually distinct}\},
\end{align*}
we have $c_d\tilde{J}_0\subset \vec{c}\cdot A$.

\label{thm:DynamicalVersion}
Let $(X,\mu,T)$ be an ergodic measure preserving $G$-system and let $(c_1,\dots,c_d)\in \mathbb Z^d$ be coefficients satisfying hypotheses (1)-(3) of Theorem \ref{thm:GeneralBogoliouboff}.  If $f_1,\dots, f_d:X\to [0,1]$ are measurable functions, $L:G^d\to [0,1]$ is defined as
\begin{equation}\label{eqn:Ldef}
L(g_1,\dots,g_{d-1};t):= \int T_{t-\sum_{j<d} c_jg_j}f_{d}\cdot \prod_{j< d} T_{c_dg_j}f_{j} \, d\mu
\end{equation}
 and $I(t)$ is defined as the iterated limit
\begin{equation}\label{eqn:defIg}
I(t):=\lim_{n_1\to \infty} \dots  \lim_{n_{d-1}\to \infty} \frac{1}{|F_{n_1}|\cdots |F_{n_{d-1}}|} \sum_{\substack{g_1\in F_{n_1}\\ \dots \\ g_{d-1}\in F_{n_{d-1}}}}L(g_1,\dots,g_{d-1};t)
\end{equation}
 then there are \begin{enumerate}
\item[$\bullet$] a compact metrizable abelian group $K$ with Haar measure $m$,

\item[$\bullet$] a homomorphism $\rho:G\to K$ having $\overline{\rho(G)}=K$,

\item[$\bullet$] functions $\tilde{f}_i:K\to [0,1]$ with $\int \tilde{f}_i\, dm = \int f_i\, d\mu $ for $i\leq d$
\end{enumerate}
such that
\begin{equation}\label{eqn:IgReduction}
I(t):=\int \tilde{f}_d\Bigl(k+\rho(t)-\sum_{j<d}c_js_j\Bigr) \prod_{j<d} \tilde{f}_j(k+c_ds_j) \, dk\, ds_1\, \dots\, ds_{d-1}.
\end{equation}
Furthermore, the $\tilde{f}_i$ depend only on the $f_i$, so if $f_1=\cdots=f_d$, then $\tilde{f}_1=\cdots=\tilde{f}_d$.

\label{rem:PositiveLimitImpliesPositive}
  With $L$ and $I$ as in Theorem \ref{thm:DynamicalVersion}, let
   \[
   L_0:=\{t\in G: \exists g_1,\dots, g_{d-1} \text{ with } L(g_1,\dots,g_{d-1};t)>0 \text{ and } c_ig_i \text{ mutually distinct}\}
   \]
   Then $\{t\in G: I(t)>0\}\subset L_0$.

\label{prop:Correspondence}
  Let $A\subset G$ have $d^*(A)=\delta$.  There is an ergodic $G$-system $(X,\mu,T)$ and a $\mu$-measurable $f:X\to [0,1]$ with $\int f\, d\mu=\delta$ such that for all $g_1,g_2,\dots,g_d\in G$, we have
  \begin{equation}\label{eqn:Correspondence}
    d^*\bigl(\bigl\{h:1_A(h + g_1)1_A(h+g_2)\dots 1_A(h+g_d)>0\bigr\}\bigr) \geq \int \prod_{i=1}^d f(T_{g_i}x)\, d\mu(x)
  \end{equation}

\label{cor:Correspondence2}
  If $A\subset G$, $c_i\in \mathbb Z$, and $\tilde{J}$ is defined as in Lemma \ref{lem:Convolution}, then there is an ergodic $G$-system $(X,\mu,T)$ and $f:X\to [0,1]$ such that
\begin{equation}\label{eqn:JgeqL}
\tilde{J}(g_1,\dots,g_{d-1};t) \geq L(g_1,\dots,g_{d-1};t) \qquad \text{for all } g_i, t\in G,
\end{equation}
where $L$ is as defined in (\ref{eqn:Ldef}), with $f_1=\dots=f_d=f$.

\label{cor:Ergodic}
  Let $(X,\mu,T)$ be a $G$-system and $f\in L^2(\mu)$.  Then
  \[\lim_{n\to \infty} \frac{1}{|F_n|}\sum_{g\in F_n} T_gf =P_{\mathcal I}f,\] where $P_{\mathcal I}$ is the orthogonal projection onto the closed subspace of $L^2(\mu)$ consisting of $T$-invariant functions.

\label{lem:RothReduce}
  If $p\in L^2(\mu)$ and $q\in \mathcal{WM}$, $a,b\in G$, and both $bG$ and $(b-a)G$ have finite index in $G$, then
  \begin{equation}\label{eqn:agbg}
  \lim_{n\to\infty} \frac{1}{|F_n|}\sum_{g\in F_n} T_{ag}p\,T_{bg}q= 0
  \end{equation}
  in $L^2(\mu)$.
